python.update_task.py:
import os, json, logging, boto3
from botocore.exceptions import ClientError

logger = logging.getLogger()
logger.setLevel(logging.INFO)

dynamodb = boto3.resource('dynamodb')
table = dynamodb.Table(os.environ['TABLE_NAME'])

def lambda_handler(event, context):
    try:
        task_id = event.get('pathParameters', {}).get('id')
        if not task_id:
            return {'statusCode': 400, 'headers': {'Content-Type': 'application/json'}, 'body': json.dumps({'error': 'Task ID missing'})}
        body = json.loads(event.get('body', '{}'))
        update_expressions = []
        expression_attribute_values = {}
        if 'title' in body:
            update_expressions.append('title = :title')
            expression_attribute_values[':title'] = body['title']
        if 'description' in body:
            update_expressions.append('description = :description')
            expression_attribute_values[':description'] = body['description']
        if not update_expressions:
            return {'statusCode': 400, 'headers': {'Content-Type': 'application/json'}, 'body': json.dumps({'error': 'No fields to update'})}
        update_expression = 'SET ' + ', '.join(update_expressions)
        response = table.update_item(
            Key={'task_id': task_id},
            UpdateExpression=update_expression,
            ExpressionAttributeValues=expression_attribute_values,
            ReturnValues='ALL_NEW'
        )
        updated_item = response.get('Attributes')
        return {'statusCode': 200, 'headers': {'Content-Type': 'application/json'}, 'body': json.dumps(updated_item)}
    except ClientError as e:
        logger.error(f'DynamoDB error: {e}')
        return {'statusCode': 500, 'headers': {'Content-Type': 'application/json'}, 'body': json.dumps({'error': 'Internal server error'})}
    except Exception as e:
        logger.error(f'Unexpected error: {e}')
        return {'statusCode': 500, 'headers': {'Content-Type': 'application/json'}, 'body': json.dumps({'error': 'Internal server error'})}

